############ zimmCheckbox/index.tsx ############
     1	import React from 'react';
     2	import { Box, Checkbox, Flex, Text } from '@chakra-ui/react';
     3	import { useIntl } from 'react-intl';
     4	import { ADD_FILTER, REMOVE_FILTER } from 'app/utils/refinementValues';
     5	
     6	export type ZimmCheckboxProps = {
     7	  value: string;
     8	  label: string;
     9	  isChecked: boolean;
    10	  onChange: (value: string, isCurrentlySelected: boolean) => void;
    11	  /** When 0 and not selected the option is hidden — pass undefined to always show. */
    12	  hitCount?: number;
    13	  /** Renders a filled colour dot beside the label when set (e.g. a CSS colour string). */
    14	  swatchColour?: string;
    15	};
    16	
    17	/**
    18	 * Single branded checkbox row with optional colour swatch. Handles its own
    19	 * hit-count visibility guard and aria-label state (Add / Remove filter).
    20	 *
    21	 * For lists of options, compose via `ZimmCheckboxGroup`.
    22	 */
    23	export const ZimmCheckbox = ({ value, label, isChecked, onChange, hitCount, swatchColour }: ZimmCheckboxProps) => {
    24	  const intl = useIntl();
    25	
    26	  if (hitCount === 0 && !isChecked) return null;
    27	
    28	  return (
    29	    <Checkbox
    30	      isChecked={isChecked}
    31	      onChange={() => onChange(value, isChecked)}
    32	      aria-label={intl.formatMessage(isChecked ? REMOVE_FILTER : ADD_FILTER, { label })}
    33	      spacing="var(--zimm-scale-s)"
    34	      sx={{
    35	        '.chakra-checkbox__control': {
    36	          borderColor: 'var(--zimm-color-border-default)',
    37	          _checked: {
    38	            background: 'var(--zimm-color-action-primary-bg-default)',
    39	            borderColor: 'var(--zimm-color-action-primary-bg-default)',
    40	            color: 'var(--zimm-color-action-primary-text)',
    41	          },
    42	          // Brand focus ring — dropping the indicator fails WCAG 2.2 AA SC 2.4.7.
    43	          _focusVisible: {
    44	            outline: 'var(--zimm-focus-ring)',
    45	            outlineOffset: 0,
    46	            boxShadow: 'none',
    47	          },
    48	        },
    49	      }}
    50	    >
    51	      <Flex align="center" gap="var(--zimm-scale-s)">
    52	        {swatchColour !== undefined && (
    53	          <Box
    54	            data-testid="zimm-colour-swatch"
    55	            boxSize="var(--zimm-icon-size-md)"
    56	            borderRadius="full"
    57	            border="var(--zimm-border-width-default) solid var(--zimm-color-border-default)"
    58	            flexShrink={0}
    59	            background={swatchColour || 'transparent'}
    60	          />
    61	        )}
    62	        <Text as="span" textStyle="navigation">
    63	          {label}
    64	        </Text>
    65	      </Flex>
    66	    </Checkbox>
    67	  );
    68	};

############ zimmSelectedChip/index.tsx ############
     1	import React from 'react';
     2	import { useIntl } from 'react-intl';
     3	import { Flex, Text } from '@chakra-ui/react';
     4	import { ZimmIcon } from '../zimmIcon';
     5	import { REMOVE_FILTER } from 'app/utils/refinementValues';
     6	
     7	type ZimmSelectedChipProps = {
     8	  label: string;
     9	  onRemove: () => void;
    10	  /** Figma Chips component (node 40007982:184470) — Primary/Secondary variant.
    11	   *  'primary' (default): filled black background, inverse label.
    12	   *  'secondary': transparent background, dark 1px border and label. */
    13	  variant?: 'primary' | 'secondary';
    14	  /** Renders the chip in the disabled state — inert, visually muted. */
    15	  isDisabled?: boolean;
    16	};
    17	
    18	/**
    19	 * Branded chip used for selected refinements in the SFCC-847 filter drawer
    20	 * (`primary`, shown as a selected-value tag above the accordion panel) and the
    21	 * page-level applied-filter bar (`secondary`, shown above the product grid).
    22	 *
    23	 * Implements the full Figma Chips component state machine (node 40007982:184470):
    24	 * Default · Hover · Pressed · Focused · Disabled — for both Primary and Secondary
    25	 * variants. Tokens match `zimmButton.css.ts`'s `primary`/`secondary` variant at the
    26	 * chip's own 32px height tier.
    27	 *
    28	 * SFCC-108 introduces a dedicated chip design system component; this atom is retired
    29	 * at that point.
    30	 *
    31	 * @param props see ZimmSelectedChipProps
    32	 */
    33	export const ZimmSelectedChip = ({ label, onRemove, variant = 'primary', isDisabled }: ZimmSelectedChipProps) => {
    34	  const intl = useIntl();
    35	  const isPrimary = variant === 'primary';
    36	
    37	  return (
    38	    <Flex
    39	      as="button"
    40	      type="button"
    41	      display="inline-flex"
    42	      alignItems="center"
    43	      justifyContent="center"
    44	      gap="var(--zimm-scale-2xs)"           // 4px — Figma alias/space/100
    45	      paddingInline="var(--zimm-scale-s)"   // 12px — Figma alias/space/300
    46	      height="var(--zimm-scale-2xl)"        // 32px — Figma --scale/800
    47	      minWidth="var(--zimm-scale-5xl)"      // 80px — Figma min-w-[80px]
    48	      position="relative"
    49	      overflow="hidden"
    50	      flexShrink={0}
    51	      disabled={isDisabled}
    52	      onClick={onRemove}
    53	      aria-label={intl.formatMessage(REMOVE_FILTER, { label })}
    54	      transition="background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease"
    55	      sx={
    56	        isPrimary
    57	          ? {
    58	              bg: 'var(--zimm-color-text-default)',
    59	              color: 'var(--zimm-color-text-inverse)',
    60	              border: 'none',
    61	              cursor: isDisabled ? 'not-allowed' : 'pointer',
    62	              _hover: {
    63	                bg: 'var(--zimm-color-text-inverse-grey)',
    64	              },
    65	              _active: {
    66	                bg: 'var(--zimm-color-action-primary-bg-pressed)',
    67	              },
    68	              _disabled: {
    69	                bg: 'var(--zimm-color-border-secondary)',
    70	                color: 'var(--zimm-color-action-primary-text-disabled)',
    71	                cursor: 'not-allowed',
    72	              },
    73	              _focusVisible: {
    74	                outline: 'var(--zimm-focus-ring)',
    75	                outlineOffset: 'var(--zimm-focus-ring-offset-default)',
    76	                boxShadow: 'none',
    77	              },
    78	            }
    79	          : {
    80	              bg: 'transparent',
    81	              color: 'var(--zimm-color-text-default)',
    82	              borderWidth: 'var(--zimm-border-width-default)',
    83	              borderStyle: 'solid',
    84	              borderColor: 'var(--zimm-color-text-default)',
    85	              cursor: isDisabled ? 'not-allowed' : 'pointer',
    86	              _hover: {
    87	                bg: 'var(--zimm-color-bg-01)',
    88	                borderColor: 'var(--zimm-color-text-default)',
    89	              },
    90	              _active: {
    91	                bg: 'var(--zimm-color-action-primary-bg-pressed)',
    92	                borderColor: 'var(--zimm-color-action-primary-bg-pressed)',
    93	                color: 'var(--zimm-color-text-inverse)',
    94	              },
    95	              _disabled: {
    96	                borderColor: 'var(--zimm-color-text-inverse-grey)',
    97	                color: 'var(--zimm-color-text-muted)',
    98	                cursor: 'not-allowed',
    99	              },
   100	              _focusVisible: {
   101	                outline: 'var(--zimm-focus-ring)',
   102	                // 3px offset clears the 1px border — same as zimmButton secondary variant.
   103	                outlineOffset: 'var(--zimm-focus-ring-offset-secondary)',
   104	                boxShadow: 'none',
   105	              },
   106	            }
   107	      }
   108	    >
   109	      {/* pointerEvents:none keeps clicks from landing on the Text/Icon children instead of
   110	          the button element, which would cause the event.target check in some click handlers
   111	          to miss the button's own bounds. */}
   112	      <Text as="span" textStyle="buttonSm" pointerEvents="none">
   113	        {label}
   114	      </Text>
   115	      {/* Decorative — the chip's own aria-label above already announces "Remove filter: …". */}
   116	      <ZimmIcon type="close" size="md" aria-hidden={true} />
   117	    </Flex>
   118	  );
   119	};

############ zimmSizeFilter/index.tsx ############
     1	import React from 'react';
     2	import { Box, SimpleGrid, Stack, Text } from '@chakra-ui/react';
     3	import { useIntl } from 'react-intl';
     4	import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
     5	import { ADD_FILTER, REMOVE_FILTER } from 'app/utils/refinementValues';
     6	import type { ShopperSearchTypes } from 'commerce-sdk-isomorphic';
     7	
     8	type ZimmSizeFilterProps = {
     9	  filter: { attributeId: string; values?: ShopperSearchTypes.ProductSearchRefinementValue[] };
    10	  toggleFilter: (value: { value: string | number }, attributeId: string, selected: boolean) => void;
    11	  selectedFilters: readonly string[];
    12	};
    13	
    14	/** One flat grid of size chips using the OOTB fixed 44px column width. */
    15	const SizeChipRow = ({ filter, toggleFilter, selectedFilters }: ZimmSizeFilterProps) => {
    16	  const intl = useIntl();
    17	
    18	  return (
    19	    <SimpleGrid columns={4} spacing="var(--zimm-scale-2xs)" marginTop="var(--zimm-scale-2xs)">
    20	      {filter.values?.map((value) => {
    21	        const isSelected = selectedFilters.some((filterValue) => filterValue == value.value);
    22	        if (value.hitCount === 0 && !isSelected) return null;
    23	
    24	        return (
    25	          <ZimmButton
    26	            key={String(value.value)}
    27	            variant={isSelected ? 'primary' : 'secondary'}
    28	            size="medium"
    29	            label={value.label}
    30	            ariaLabel={intl.formatMessage(isSelected ? REMOVE_FILTER : ADD_FILTER, { label: value.label })}
    31	            role="checkbox"
    32	            ariaChecked={isSelected}
    33	            onClick={() => toggleFilter(value, filter.attributeId, isSelected)}
    34	            sx={{
    35	              ...(isSelected
    36	                ? {}
    37	                : {
    38	                    borderColor: 'var(--zimm-color-border-secondary)',
    39	                    _hover: { borderColor: 'var(--zimm-color-border-secondary)' },
    40	                  }),
    41	            }}
    42	          />
    43	        );
    44	      })}
    45	    </SimpleGrid>
    46	  );
    47	};
    48	
    49	/**
    50	 * SFCC-847 — the Size facet's chip row, plus sub-group headings (e.g. Clothing/Accessories/
    51	 * Shoes) when SFCC returns c_size as nested groups — the same nesting
    52	 * `flattenRefinementValues` (overrides/app/utils/refinementValues.ts) already anticipates. A
    53	 * flat (ungrouped) c_size refinement renders as a single ungrouped row.
    54	 *
    55	 * Grouping depends entirely on the shape SFCC sends: the API currently returns c_size flat, so
    56	 * the ungrouped branch is what renders today. Producing the grouped design is BM configuration
    57	 * (nested parent values), not a front-end change.
    58	 *
    59	 * @param props see ZimmSizeFilterProps
    60	 */
    61	export const ZimmSizeFilter = ({ filter, toggleFilter, selectedFilters }: ZimmSizeFilterProps) => {
    62	  const groups = filter.values ?? [];
    63	  const isNested = groups.some((group) => group.values && group.values.length > 0);
    64	
    65	  if (!isNested) {
    66	    return <SizeChipRow filter={filter} toggleFilter={toggleFilter} selectedFilters={selectedFilters} />;
    67	  }
    68	
    69	  return (
    70	    <Stack sx={{ gap: 'var(--zimm-scale-m)' }}>
    71	      {groups.map((group) => (
    72	        <Box key={String(group.value)}>
    73	          {/* Sub-group heading (Clothing / Accessories / Shoes). `textStyle="body2Strong"`
    74	              matches the design system's 14/18 medium letterSpacing entry; the earlier
    75	              `fontStyle="italic"` was speculative and had no Figma reference (audited
    76	              2026-09-16). */}
    77	          <Text textStyle="body2Strong" marginBottom="var(--zimm-scale-xs)">
    78	            {group.label}
    79	          </Text>
    80	          <SizeChipRow
    81	            filter={{ attributeId: filter.attributeId, values: group.values }}
    82	            toggleFilter={toggleFilter}
    83	            selectedFilters={selectedFilters}
    84	          />
    85	        </Box>
    86	      ))}
    87	    </Stack>
    88	  );
    89	};

