     1	import { useLayoutEffect, useState } from 'react';
     2	
     3	export type PendingRefinements = Record<string, string[]>;
     4	
     5	type UseFilterDrawerStateParams = {
     6	  /** Whether the filter drawer is currently open — pending state resyncs from the
     7	   *  currently-applied filters every time this transitions to true. */
     8	  isOpen: boolean;
     9	  /**
    10	   * The category ID currently reflected in the URL — used as the initial pending
    11	   * category selection each time the drawer opens. Pass `params.categoryId` for a
    12	   * standard single-category page, or `undefined` when no sub-category is active.
    13	   */
    14	  categoryId?: string;
    15	  /** The currently-applied refinements — pass searchParams.refine (the real URL-derived
    16	   *  ground truth), NOT productSearchResult.selectedRefinements (the SFCC API field that
    17	   *  only reflects what the backend chose to echo back, which is often incomplete).
    18	   *  Values may be a pipe-separated string ('Black|White'), an array, or a number. */
    19	  selectedRefinements?: Record<string, string | number | (string | number)[] | undefined>;
    20	};
    21	
    22	type UseFilterDrawerStateReturn = {
    23	  /** The category currently pending selection in the drawer, or undefined if none. */
    24	  pendingCategoryId: string | undefined;
    25	  /** Replaces the pending category — use to set a new selection or clear (pass undefined). */
    26	  setPendingCategoryId: (id: string | undefined) => void;
    27	  pendingRefine: PendingRefinements;
    28	  setValues: (attributeId: string, values: string[]) => void;
    29	  removeValue: (attributeId: string, value: string) => void;
    30	  clearAll: () => void;
    31	  /** Re-derives pendingRefine from a (possibly different) selectedRefinements snapshot —
    32	   *  same parsing the drawer-open resync uses. For a caller that reverts a pending category
    33	   *  change back to the currently-applied category (e.g. removing the category chip): that
    34	   *  category change already cleared pendingRefine via clearAll, so reverting it must also
    35	   *  restore whatever refine is actually still applied, not leave the buffer empty. */
    36	  resyncPendingRefine: (selectedRefinements?: UseFilterDrawerStateParams['selectedRefinements']) => void;
    37	};
    38	
    39	/**
    40	 * Parses a searchParams.refine-shaped object into the buffered PendingRefinements shape —
    41	 * split out so both the drawer-open resync effect and a caller-triggered resync
    42	 * (resyncPendingRefine) share one implementation.
    43	 */
    44	const parseSelectedRefinements = (
    45	  selectedRefinements: UseFilterDrawerStateParams['selectedRefinements'],
    46	): PendingRefinements => {
    47	  const initial: PendingRefinements = {};
    48	  Object.entries(selectedRefinements ?? {}).forEach(([attributeId, rawValue]) => {
    49	    if (attributeId === 'cgid' || rawValue == null) return;
    50	    // searchParams.refine values can be arrays (from buildAppliedRefine), pipe-separated
    51	    // strings ('Black|White' — SFCC URL encoding), or plain numbers. Handle all three so
    52	    // the resync works correctly regardless of whether the value was round-tripped through
    53	    // the URL parser or set directly.
    54	    const values: string[] = Array.isArray(rawValue) ? rawValue.map(String) : String(rawValue).split('|');
    55	    if (values.length > 0 && values[0] !== '') initial[attributeId] = values;
    56	  });
    57	  return initial;
    58	};
    59	
    60	/**
    61	 * Buffers SFCC-847 filter-drawer selections (category + every refinement facet) in local
    62	 * state instead of applying each click straight to the URL/product grid. Resyncs from the
    63	 * page's currently-applied filters every time the drawer opens, so a value chosen and then
    64	 * abandoned (drawer closed without pressing APPLY) never reaches the URL, and reopening
    65	 * after a previous APPLY reflects reality rather than stale local state.
    66	 *
    67	 * @returns pending category/refinement selections plus mutators. The caller is responsible
    68	 * for actually applying them (navigating) when the shopper presses APPLY.
    69	 */
    70	export const useFilterDrawerState = ({
    71	  isOpen,
    72	  categoryId,
    73	  selectedRefinements,
    74	}: UseFilterDrawerStateParams): UseFilterDrawerStateReturn => {
    75	  const [pendingCategoryId, setPendingCategoryId] = useState<string | undefined>(categoryId);
    76	  const [pendingRefine, setPendingRefine] = useState<PendingRefinements>({});
    77	
    78	  // useLayoutEffect (not useEffect) — runs synchronously after DOM commit and before the
    79	  // browser paints. This prevents the visible flash of stale checkbox state that useEffect
    80	  // causes: with useEffect the drawer renders once with the previous pendingRefine (user
    81	  // briefly sees wrong checked state), then the effect fires and corrects it. The filter
    82	  // drawer is always closed during SSR so the isOpen guard means this body never runs
    83	  // server-side — the layout-effect SSR warning does not apply here.
    84	  useLayoutEffect(() => {
    85	    if (!isOpen) return;
    86	    setPendingRefine(parseSelectedRefinements(selectedRefinements));
    87	    setPendingCategoryId(categoryId);
    88	    // Resync is keyed on `isOpen` alone. `categoryId`/`selectedRefinements` change on every
    89	    // navigation — including the one APPLY itself triggers — so including them here would
    90	    // re-run this effect right after APPLY and stomp the just-applied selection straight
    91	    // back to whatever the next render resolves it to.
    92	  }, [isOpen]);
    93	
    94	  const resyncPendingRefine = (nextSelectedRefinements?: UseFilterDrawerStateParams['selectedRefinements']) => {
    95	    setPendingRefine(parseSelectedRefinements(nextSelectedRefinements));
    96	  };
    97	
    98	  const setValues = (attributeId: string, values: string[]) => {
    99	    setPendingRefine((prev) => {
   100	      if (values.length === 0) {
   101	        const { [attributeId]: _removed, ...rest } = prev;
   102	        return rest;
   103	      }
   104	      return { ...prev, [attributeId]: values };
   105	    });
   106	  };
   107	
   108	  const removeValue = (attributeId: string, value: string) => {
   109	    setPendingRefine((prev) => {
   110	      const next = (prev[attributeId] ?? []).filter((v) => v !== value);
   111	      if (next.length === 0) {
   112	        const { [attributeId]: _removed, ...rest } = prev;
   113	        return rest;
   114	      }
   115	      return { ...prev, [attributeId]: next };
   116	    });
   117	  };
   118	
   119	  const clearAll = () => setPendingRefine({});
   120	
   121	  return {
   122	    pendingCategoryId,
   123	    setPendingCategoryId,
   124	    pendingRefine,
   125	    setValues,
   126	    removeValue,
   127	    clearAll,
   128	    resyncPendingRefine,
   129	  };
   130	};
   131	
   132	export type AppliedRefine = Record<string, string | number | (string | number)[]>;
   133	
   134	/**
   135	 * Merges buffered facet selections into the page's real `searchParams.refine` object —
   136	 * the pure computation behind the drawer's APPLY handler, split out so it's testable
   137	 * without a component or navigation. Every attribute this drawer manages (every non-cgid
   138	 * attributeId SFCC currently returns as a refinement) is fully overwritten from
   139	 * `pendingRefine` — including being deleted if the shopper unticked it back to empty —
   140	 * while any attribute this drawer does not manage (e.g. StoreInventoryFilter's `ilids`) is
   141	 * left exactly as it was in `currentRefine`.
   142	 *
   143	 * @returns a new refine object; never mutates `currentRefine`.
   144	 */
   145	export const buildAppliedRefine = (
   146	  currentRefine: AppliedRefine,
   147	  managedAttributeIds: string[],
   148	  pendingRefine: PendingRefinements,
   149	): AppliedRefine => {
   150	  const nextRefine: AppliedRefine = { ...currentRefine };
   151	  const managedSet = new Set(managedAttributeIds);
   152	  managedSet.forEach((attributeId) => {
   153	    delete nextRefine[attributeId];
   154	  });
   155	  // Only write back attributes this drawer manages — unmanaged ones (e.g. ilids) are already
   156	  // preserved from the { ...currentRefine } spread above and must not be overwritten with the
   157	  // array-converted form that parseSelectedRefinements produces.
   158	  Object.entries(pendingRefine).forEach(([attributeId, values]) => {
   159	    if (managedSet.has(attributeId)) {
   160	      nextRefine[attributeId] = values;
   161	    }
   162	  });
   163	  return nextRefine;
   164	};

