     1	import React from 'react';
     2	import type { Meta, StoryObj } from '@storybook/react-webpack5';
     3	import { expect, userEvent, within } from 'storybook/test';
     4	import { ZimmAccordion } from './index';
     5	
     6	const meta: Meta<typeof ZimmAccordion> = {
     7	  title: 'Elements/ZimmAccordion',
     8	  component: ZimmAccordion,
     9	};
    10	export default meta;
    11	type Story = StoryObj<typeof ZimmAccordion>;
    12	
    13	// Deliberately generic labels — the SFCC-847 filter labels (Category / Colour / Size /
    14	// Material / Sleeve Length / Availability) belong on the ZimmFiltersDrawerContent stories,
    15	// not this atom's. This story asserts the primitive's contract in isolation.
    16	const SAMPLE_ITEMS = [
    17	  { id: 'alpha', label: 'Alpha', content: <p>Alpha content.</p> },
    18	  { id: 'beta', label: 'Beta', content: <p>Beta content.</p> },
    19	  { id: 'gamma', label: 'Gamma', content: <p>Gamma content.</p> },
    20	];
    21	
    22	export const Default: Story = {
    23	  args: { items: SAMPLE_ITEMS },
    24	};
    25	
    26	export const WithDefaultExpanded: Story = {
    27	  args: { items: SAMPLE_ITEMS, defaultExpandedId: 'alpha' },
    28	};
    29	
    30	export const ClickTogglesExpansion: Story = {
    31	  args: { items: SAMPLE_ITEMS },
    32	  play: async ({ canvasElement }) => {
    33	    const canvas = within(canvasElement);
    34	    const alphaHeader = canvas.getByRole('button', { name: /alpha/i });
    35	    await expect(alphaHeader).toHaveAttribute('aria-expanded', 'false');
    36	    await userEvent.click(alphaHeader);
    37	    await expect(alphaHeader).toHaveAttribute('aria-expanded', 'true');
    38	    // Clicking the same header again collapses it (Chakra's `allowToggle` behaviour, which
    39	    // SFCC-847 does not contradict — the AC's "one expanded at a time" rule doesn't require
    40	    // that at least one is always open).
    41	    await userEvent.click(alphaHeader);
    42	    await expect(alphaHeader).toHaveAttribute('aria-expanded', 'false');
    43	  },
    44	};
    45	
    46	// AC covered: "expanding a new accordion collapses the previously expanded one." Asserted
    47	// via aria-expanded rather than a visible/hidden panel query — the underlying `AccordionPanel`
    48	// mounts unconditionally and Chakra hides it via CSS, so a panel presence assertion would
    49	// pass either way. aria-expanded is the actual behavioural contract for assistive tech.
    50	export const OnlyOneExpandedAtATime: Story = {
    51	  args: { items: SAMPLE_ITEMS, defaultExpandedId: 'alpha' },
    52	  play: async ({ canvasElement }) => {
    53	    const canvas = within(canvasElement);
    54	    const alphaHeader = canvas.getByRole('button', { name: /alpha/i });
    55	    const betaHeader = canvas.getByRole('button', { name: /beta/i });
    56	    await expect(alphaHeader).toHaveAttribute('aria-expanded', 'true');
    57	    await expect(betaHeader).toHaveAttribute('aria-expanded', 'false');
    58	    await userEvent.click(betaHeader);
    59	    await expect(alphaHeader).toHaveAttribute('aria-expanded', 'false');
    60	    await expect(betaHeader).toHaveAttribute('aria-expanded', 'true');
    61	  },
    62	};

